import java.util.*;

class Solution {
    public int maxProfitFee(int[] prices, int fee) {
        int free = 0, hold = -prices[0];
        for (int i = 1; i < prices.length; i++) {
            int p = prices[i];
            int newFree = Math.max(free, hold + p - fee);  // sell today, pay the fee
            int newHold = Math.max(hold, free - p);        // buy today
            free = newFree; hold = newHold;
        }
        return free;
    }
}

