function maxProfitFee(prices, fee) {
  let free = 0, hold = -prices[0] - fee;
  for (let i = 1; i < prices.length; i++) {
    const p = prices[i];
    const nf = Math.max(free, hold + p);
    hold = Math.max(hold, free - p - fee);
    free = nf;
  }
  return free;
}
